'use strict';
// Calls are resolved after ron; pon/kan have priority over chi, then seat order.
const oldRender=render,oldActions=renderActions,oldCpu=cpu,oldEvaluate=evaluate;
stored=function(){try{let d=JSON.parse(localStorage.getItem(KEY));if(!d||d.players?.length!==4)return null;if(d.version===1){let known=[d.dora,d.ura,...d.deck,...d.players.flatMap(p=>[...p.hand,...p.river.map(r=>r.t)])],c=MJ.counts(known),remaining=[];for(let t=0;t<34;t++)for(let n=c[t];n<4;n++)remaining.push(t);if(remaining.length!==12)return null;d.players.forEach(p=>p.melds=[]);d.indicators=[d.dora,d.ura,...remaining.slice(0,8)];d.replacements=remaining.slice(8);d.deadUsed=[];d.kanCount=0;d.doras=[d.dora];d.uras=[d.ura];d.pendingKan=null;d.rinshan=false;d.afterCall=false;d.forbidden=[];d.version=2}return d.version===2?d:null}catch{return null}};
evaluate=function(i,tsumo,t){if(tsumo&&G.afterCall)return null;return oldEvaluate(i,tsumo,t)};
newRound=function(){let deck=Array.from({length:136},(_,i)=>i>>2);for(const t of [4,13,22])deck[t*4]=t+.1;for(let i=135;i>0;i--){let j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}let dead=deck.splice(-14);G.indicators=dead.slice(0,10);G.replacements=dead.slice(10);G.deadUsed=[];G.kanCount=0;G.doras=[dead[0]];G.uras=[dead[1]];G.dora=dead[0];G.ura=dead[1];G.players.forEach(p=>{p.hand=deck.splice(0,13).sort((a,b)=>a-b);p.melds=[];p.river=[];p.riichi=false;p.doubleRiichi=false;p.drawCount=0;p.ippatsu=false;p.tempFuriten=false;p.riichiFuriten=false});G.deck=deck;G.firstTurnInterrupted=false;G.turn=G.dealer;G.phase='draw';G.lastDiscard=null;G.result=null;G.pendingKan=null;G.rinshan=false;G.afterCall=false;G.forbidden=[];selected=-1;declare=false;log(`${MJ.winds[roundWind()]}${G.round%4+1}局 ${G.honba}本場が始まりました`);G.reaction=null;announceRoundStart();playSfx('start');render();save();queue(draw)};
draw=function(){if(!G.deck.length){exhaustive();return}G.phase='discard';G.afterCall=false;G.rinshan=false;G.forbidden=[];let p=G.players[G.turn];p.hand.sort((a,b)=>a-b);p.hand.push(G.deck.pop());p.drawCount=(p.drawCount||0)+1;p.tempFuriten=false;selected=-1;declare=false;save();render();continueTurn()};
function continueTurn(){if(G.turn!==0)queue(cpu);else if(G.players[0].riichi&&!evaluate(0,true,G.players[0].hand.at(-1))&&!kanOptions(0).length)queue(()=>discard(G.players[0].hand.length-1))}
function interruptIppatsu(){G.firstTurnInterrupted=true;G.players.forEach(p=>p.ippatsu=false)}
function canKan(){return G.kanCount<4&&G.deck.length>0&&G.replacements.length>0}
function kanOptions(i){let p=G.players[i];if(!canKan()||G.afterCall)return [];let c=MJ.counts(p.hand),opts=[];for(let t=0;t<34;t++)if(c[t]===4){let meld={type:'kan',tiles:[t,t,t,t],open:false,from:i,called:t};if(p.riichi){if(MJ.base(p.hand.at(-1))!==t)continue;let before=p.hand.slice(0,-1),after=p.hand.filter(v=>MJ.base(v)!==t),w=MJ.waits(before,p.melds),nw=MJ.waits(after,[...p.melds,meld]);if(JSON.stringify(w)!==JSON.stringify(nw))continue;if(w.some(v=>MJ.shapes([...before,v],p.melds).some(s=>s.type!=='normal'||!s.groups.some(g=>!g.fixed&&g.trip&&g.t===t))))continue}opts.push({kind:'ankan',t:p.hand.find(v=>MJ.base(v)===t),tiles:p.hand.filter(v=>MJ.base(v)===t)})}if(!p.riichi)p.melds.forEach((m,k)=>{if(m.type==='pon'&&c[MJ.base(m.tiles[0])]){let actual=p.hand.find(v=>MJ.base(v)===MJ.base(m.tiles[0]));opts.push({kind:'kakan',t:actual,index:k,tiles:[actual]})}});return opts}
function callOptions(i,from,t){const actual=t;t=MJ.base(t);let p=G.players[i];if(p.riichi||!G.deck.length||p.melds.length>=4)return [];let c=MJ.counts(p.hand),opts=[];if(c[t]>=2)opts.push({i,kind:'pon',take:[t,t],tiles:[t,t,t],priority:2,forbidden:[t]});if(c[t]>=3&&canKan())opts.push({i,kind:'minkan',take:[t,t,t],tiles:[t,t,t,t],priority:2,forbidden:[]});if(i===(from+1)%4&&t<27)for(let lo=t-2;lo<=t;lo++){if(lo<0||lo%9>6||Math.floor(lo/9)!==Math.floor(t/9))continue;let seq=[lo,lo+1,lo+2],take=seq.filter(v=>v!==t);if(take.every(v=>c[v])){let forbidden=[t];if(t===lo&&lo%9<=5)forbidden.push(lo+3);if(t===lo+2&&lo%9>=1)forbidden.push(lo-1);opts.push({i,kind:'chi',take,tiles:seq,priority:1,forbidden})}}opts=opts.map(o=>{let rest=p.hand.slice(),take=o.take.map(v=>{let k=rest.indexOf(v);if(k<0)k=rest.findIndex(a=>MJ.base(a)===v);return rest.splice(k,1)[0]});return {...o,take,tiles:[...take,actual].sort((a,b)=>a-b)}});return opts.filter(o=>{if(o.kind==='minkan')return true;let rest=p.hand.slice();o.take.forEach(v=>rest.splice(rest.indexOf(v),1));return rest.some(v=>!o.forbidden.includes(MJ.base(v)))})}
function aiCall(i,from,t){let p=G.players[i],options=callOptions(i,from,t);let before=MJ.shanten(p.hand,p.melds.length);let best=null;for(let o of options){let hand=p.hand.slice();o.take.forEach(v=>hand.splice(hand.indexOf(v),1));let meld={type:o.kind==='minkan'?'kan':o.kind,tiles:o.tiles,open:true};let melds=[...p.melds,meld];let all=[...hand,...melds.flatMap(m=>m.tiles)];let yakuhai=melds.some(m=>m.type!=='chi'&&(m.tiles[0]>=31||m.tiles[0]===27+wind(i)||m.tiles[0]===27+roundWind()));let tanyao=all.every(t=>!MJ.terminal(t));if(!yakuhai&&!tanyao)continue;let sh=o.kind==='minkan'?MJ.shanten(hand,melds.length):Math.min(...hand.map((t,j)=>o.forbidden.includes(MJ.base(t))?99:MJ.shanten(hand.filter((_,k)=>k!==j),melds.length)));if(sh<before||(o.kind==='minkan'&&sh<=before)){if(!best||sh<best.sh)best={...o,sh}}}return best}
discard=function(idx,newRiichi=false){let i=G.turn,p=G.players[i];if(G.phase!=='discard'||idx<0||idx>=p.hand.length||(G.forbidden||[]).includes(MJ.base(p.hand[idx])))return;if(p.riichi&&!newRiichi&&idx!==p.hand.length-1)return;if(newRiichi)p.doubleRiichi=p.river.length===0&&p.drawCount===1&&G.firstTurnInterrupted===false;let t=p.hand.splice(idx,1)[0];if(!newRiichi)p.ippatsu=false;p.river.push({t,riichi:newRiichi});p.hand.sort((a,b)=>a-b);G.lastDiscard={i,t};G.phase='draw';G.rinshan=false;G.afterCall=false;G.forbidden=[];selected=-1;declare=false;playSfx(newRiichi?'riichi':'discard');if(newRiichi)say(i,'riichi');else if(i&&Math.random()<.16)say(i,'discard');log(p.name+'：'+MJ.names[t]+(newRiichi?'（リーチ）':''));if(newRiichi&&i)showCutIn(i,'riichi');resolveRon(()=>offerCalls())};
function resolveRon(next){let {i,t}=G.lastDiscard,candidates=[];for(let n=1;n<=3;n++){let j=(i+n)%4,r=canRon(j,t);if(G.pendingKan?.kind==='ankan'&&!r?.yaku.some(y=>y[0]==='国士無双'||y[0]==='国士無双十三面待ち'))r=null;if(r)candidates.push({i:j,r})}if(candidates.length){G.ronCandidates=candidates;if(candidates[0].i===0){G.phase='ron';save();render();return}finishWin(candidates[0].i,i,t,candidates[0].r);return}next()}
ronActions=function(){$('#status').textContent=people[G.lastDiscard.i].name+'の'+MJ.names[G.lastDiscard.t]+'で'+(G.pendingKan?'槍槓':'ロン')+'できます';$('#actions').innerHTML='<button id="ron" class="accent">ロン</button><button id="pass" class="quiet">見送る</button>';$('#ron').onclick=()=>finishWin(0,G.lastDiscard.i,G.lastDiscard.t,G.ronCandidates[0].r);$('#pass').onclick=()=>{let p=G.players[0];p.tempFuriten=true;if(p.riichi)p.riichiFuriten=true;let other=G.ronCandidates.find(c=>c.i!==0);if(other){finishWin(other.i,G.lastDiscard.i,G.lastDiscard.t,other.r);return}if(G.pendingKan)completeKan();else offerCalls()}};
function offerCalls(){let {i:from,t}=G.lastDiscard;let cpus=[1,2,3].filter(i=>i!==from).map(i=>aiCall(i,from,t)).filter(Boolean).sort((a,b)=>b.priority-a.priority||((a.i-from+4)%4)-((b.i-from+4)%4));G.cpuCall=cpus[0]||null;G.callChoices=from===0?[]:callOptions(0,from,t).filter(o=>!G.cpuCall||o.priority>G.cpuCall.priority||o.priority===G.cpuCall.priority&&(4-from)%4<(G.cpuCall.i-from+4)%4);if(G.callChoices.length){G.phase='call';save();render();return}finishCalls()}
function finishCalls(){if(G.cpuCall){applyCall(G.cpuCall);return}G.turn=(G.lastDiscard.i+1)%4;G.phase='draw';save();render();queue(draw)}
function callLabel(o){return o.kind==='pon'?'ポン':o.kind==='chi'?'チー':o.kind==='ankan'?'暗槓':o.kind==='kakan'?'加槓':'カン'}
function callActions(){$('#status').textContent=people[G.lastDiscard.i].name+'の'+MJ.names[G.lastDiscard.t]+'を鳴けます';$('#actions').innerHTML=G.callChoices.map((o,k)=>`<button class="call-choice accent" data-call="${k}">${callLabel(o)} <span class="call-preview">${o.tiles.map(t=>tile(t)).join('')}</span></button>`).join('')+'<button id="pass-call" class="quiet">鳴かない</button>';document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>applyCall(G.callChoices[+b.dataset.call]));$('#pass-call').onclick=finishCalls}
function applyCall(o){let p=G.players[o.i],from=G.lastDiscard.i,t=G.lastDiscard.t;o.take.forEach(v=>p.hand.splice(p.hand.indexOf(v),1));let river=G.players[from].river;river[river.length-1].taken=true;p.melds.push({type:o.kind==='minkan'?'kan':o.kind,tiles:o.tiles,open:true,from,called:t});interruptIppatsu();G.turn=o.i;G.rinshan=false;G.afterCall=true;G.forbidden=o.forbidden;G.phase='discard';selected=-1;declare=false;say(o.i,o.kind==='minkan'?'kan':o.kind);playSfx(o.kind==='minkan'?'kan':o.kind);log(p.name+'が'+callLabel(o));if(o.kind==='minkan'){replacementDraw();return}save();render();if(o.i!==0)queue(cpu)}
function declareKan(o){G.pendingKan={...o,i:G.turn};G.lastDiscard={i:G.turn,t:o.t};resolveRon(completeKan)}
function completeKan(){let o=G.pendingKan,p=G.players[o.i];if(o.kind==='ankan'){p.hand=p.hand.filter(t=>MJ.base(t)!==MJ.base(o.t));p.melds.push({type:'kan',tiles:o.tiles,open:false,from:o.i,called:o.t})}else{p.hand.splice(p.hand.indexOf(o.t),1);let m=p.melds[o.index];m.tiles.push(o.t);m.type='kan'}G.turn=o.i;G.pendingKan=null;interruptIppatsu();log(p.name+'が'+callLabel(o));say(o.i,'kan');playSfx('kan');replacementDraw()}
function replacementDraw(){G.kanCount++;G.doras.push(G.indicators[G.kanCount*2]);G.uras.push(G.indicators[G.kanCount*2+1]);G.deadUsed.push(G.deck.pop());let p=G.players[G.turn];p.hand.sort((a,b)=>a-b);p.hand.push(G.replacements.pop());p.tempFuriten=false;G.rinshan=true;G.afterCall=false;G.forbidden=[];G.phase='discard';selected=-1;declare=false;save();render();continueTurn()}
cpu=function(){let i=G.turn,p=G.players[i];if(!G.afterCall&&evaluate(i,true,p.hand.at(-1))){oldCpu();return}let options=kanOptions(i);if(options.length){declareKan(options[0]);return}oldCpu()};
render=function(){oldRender();for(let i=0;i<4;i++){let target=i===0?$('#hand'):$('#seat'+i);let id='melds'+i,existing=$('#'+id);if(existing)existing.remove();let group=document.createElement('div');group.id=id;group.className='melds '+(i===0?'self-melds':'opponent-melds');group.innerHTML=G.players[i].melds.map(m=>`<span class="meld"><small>${m.type==='chi'?'チー':m.type==='pon'?'ポン':m.open?'明槓':'暗槓'}</small>${m.tiles.map((t,k)=>!m.open&&(k===0||k===3)?'<span class="tile mini back">◆</span>':tile(t)).join('')}</span>`).join('');target.insertAdjacentElement(i===0?'afterend':'beforeend',group);$('#river'+i).innerHTML=G.players[i].river.map(r=>tile(r.t,'mini',(r.riichi?'riichi-discard ':'')+(r.taken?'taken':''))).join('')}};
renderActions=function(){if(G.phase==='call'){callActions();return}oldActions();if(G.phase==='discard'&&G.turn===0){let opts=kanOptions(0);opts.forEach((o,k)=>{let b=document.createElement('button');b.className='quiet';b.textContent=callLabel(o)+'（'+MJ.names[o.t]+'）';b.onclick=()=>declareKan(o);$('#actions').appendChild(b)});if(G.players[0].riichi&&opts.length&&!evaluate(0,true,G.players[0].hand.at(-1))){let b=document.createElement('button');b.className='primary';b.textContent='ツモ切り';b.onclick=()=>discard(G.players[0].hand.length-1);$('#actions').appendChild(b)}}};
resumeButton=function(){let d=stored();$('#resume-wrap').innerHTML=d&&!d.finished?'<button id="resume" class="quiet resume">中断した対局を再開 →</button>':'';if($('#resume'))$('#resume').onclick=()=>{G=stored();enterGame();render();if(G.phase==='result')showResult();else if(G.phase==='draw')queue(draw);else if(G.phase==='discard')continueTurn()}};
resumeButton();

